(window.webpackJsonp=window.webpackJsonp||[]).push([[8],{24:function(e,n,s){"use strict";s.r(n);n.default=[{no:3,action:" Premier rappel: ton courtois. \nTu introduis le sujet du retard de paiement de mani\xe8re informelle et amicale. Tu pr\xe9sumes que le client a simplement oubli\xe9 de payer. Tu am\xe9liores et compl\xe8tes la proposition de texte ci-dessous et tu proposes encore 4 autres variantes:\n\nSimple rappel\n\nMadame, Monsieur,\nNous esp\xe9rons que vous allez bien.\nNous vous \xe9crivons pour vous rappeler que le montant de [montant] est \xe9chu.\nMerci de bien vouloir proc\xe9der au r\xe8glement dans les 10 jours.\nSi avez d\xe9j\xe0 effectu\xe9 le paiement, veuillez ignorer ce message.\nN\xb4h\xe9sitez pas \xe0 nous contacter pour toute question.\nNous vous prions d\u2019agr\xe9er, Madame, Monsieur, l\u2019expression de nos salutations distingu\xe9es.\n",fonction:null},{no:4,action:" Deuxi\xe8me rappel: ton formel. \nTu renforces le rappel en soulignant l\xb4importance et la n\xe9cessit\xe9 d\xb4un paiement rapide.\nTu am\xe9liores et compl\xe8tes la proposition de texte ci-dessous et tu proposes encore 4 autres variantes:\n\nRappel important\n\nMadame, Monsieur,\nNous nous permettons de vous rappeler que le montant de [montant] est toujours en attente de r\xe8glement, malgr\xe9 notre pr\xe9c\xe9dent message.\nNous vous remercions de bien vouloir proc\xe9der au paiement dans les plus brefs d\xe9lais.\nEn vous remerciant pour votre attention.\nSi avez d\xe9j\xe0 effectu\xe9 le paiement, veuillez ignorer ce message.\nNous vous prions d\u2019agr\xe9er, Madame, Monsieur, l\u2019expression de nos salutations distingu\xe9es.\n",fonction:null},{no:5,action:" Troisi\xe8me rappel: ton ferme. \nTu avertis le client que c\xb4est la derni\xe8re opportunit\xe9 de payer avant une mise en demeure.\nTu am\xe9liores et compl\xe8tes la proposition de texte ci-dessous et tu proposes encore 4 autres variantes:\n\nDernier rappel avant mise en demeure\n\nMadame, Monsieur,\nMalgr\xe9 plusieurs rappels, nous n\xb4avons \xe0 ce jour re\xe7u aucun paiement correspondant aux montants \xe9chus. La cr\xe9ance s\xb4\xe9l\xe8ve \xe0 CHF [montant].\nVeuillez proc\xe9der au paiement dans les plus brefs d\xe9lais.\nSi avez d\xe9j\xe0 effectu\xe9 le paiement, veuillez ignorer ce message.\nNous vous prions d\u2019agr\xe9er, Madame, Monsieur, l\u2019expression de nos salutations distingu\xe9es.\n",fonction:null},{no:6,action:" Mise en demeure: ton juridique. \nTu mets en demeure le client de payer. Tu indiquant clairement que le recouvrement de la cr\xe9ance s\xb4effectuera ensuite par voie l\xe9gale.\n\nTu am\xe9liores et compl\xe8tes la proposition de texte ci-dessous et tu proposes encore 4 autres variantes:\n\nMise en demeure de paiement\n\nMadame, Monsieur,\nH\xe9las, nos pr\xe9c\xe9dents rappels sont rest\xe9s sans effets.\nNous vous accordons un dernier d\xe9lai de paiement de 10 jours (date de r\xe9ception du paiement).\nPass\xe9 ce d\xe9lai, nous engagerons, sans pr\xe9avis, le recouvrement par voie l\xe9gale.\nEn esp\xe9rant vous \xe9viter ces d\xe9sagr\xe9ments,nous vous remercions d\xb4avance pour votre coop\xe9ration.\nVeuillez agr\xe9er, Madame, Monsieur, l\u2019expression de nos salutations distingu\xe9es.\n",fonction:null},{no:30,action:' Conclus ta mission par une liste de 3 questions qui, selon toi, devraient encore \xeatre approfondies et 3 suggestions d\xb4am\xe9liorations. \nDonne \xe0 chaque fois des exemples d\xe9taill\xe9s sur "Comment faire".',fonction:null}]}}]);
